-- Deal Hub Build Board: the Phase 1 task list v4 (84 tasks), one feature per task, grouped by phase.
-- Generated from scratchpad tasks4.mjs. Run after schema.sql. Safe to run again:
-- it updates task content, phase and stream but keeps status, assignee, notes, pull request links and the developer's approach.

on conflict (code) do update set
  title = excluded.title, phase = excluded.phase, goal = excluded.goal, story = excluded.story, module = excluded.module, stream = excluded.stream, week = excluded.week, blocking = excluded.blocking, depends = excluded.depends, uses = excluded.uses, refs = excluded.refs, files = excluded.files, api = excluded.api, acceptance = excluded.acceptance, backend = excluded.backend, frontend = excluded.frontend, checks = excluded.checks, think = excluded.think, sort = excluded.sort;

-- Tasks from earlier versions that are not in v4 (only removed while nobody has taken them; your own N-x tasks are kept).
delete from public.tasks
 where assignee is null
   and code !~ '^N-'
   and code not in ('S-1','G-1','K-1','S-2','G-2','K-2','S-3','G-3','K-3','S-4','G-4','K-4','Q-01','Q-02','Q-03','Q-04','Q-05','Q-06','Q-07','Q-08','Q-09','Q-10','P-01','P-02','P-03','P-04','P-05','P-06','P-07','M-01','M-02','M-03','M-04','M-05','M-06','M-07','M-08','M-09','M-10','V-01','V-02','V-03','V-04','V-05','V-06','V-07','C-01','C-02','C-03','C-04','C-05','C-06','A-01','A-02','A-03','A-04','A-05','A-06','A-07','A-08','A-09','U-01','U-02','U-03','U-04','U-05','F-01','F-02','F-03','F-04','F-05','F-06','F-07','F-08','F-09','X-1','X-2','X-3','X-4','X-5','Z-1','Z-2','Z-3','Z-4')
   and created_by is null;
