insert into public.tasks (code,title,phase,goal,story,module,stream,week,blocking,depends,uses,refs,files,api,acceptance,backend,frontend,checks,think,sort) values
('S-1','Run the starter and learn the guardrails (Developer 1)','Start','Clone the deal-hub starter repository, run it on your own laptop exactly as README.md says, and read the rules every change must pass. Nobody writes feature code before this is green, so all four laptops behave the same.','As Developer 1 I have the starter running locally with pnpm verify green, so that my first feature fits the same structure as everyone else''s.','Start','dev1',1,true,array[]::text[],array[]::text[],array['README.md','GUARDRAILS.md','AGENTS.md','docs/ARCHITECTURE.md','docs/APP_FLOW.md']::text[],array['backend/.env (local only, never committed)','backend/src/modules/clients/rules.test.ts']::text[],array[]::text[],array['pnpm verify passes on your laptop on the latest main','You can explain in two sentences how a request goes through defineRoute, tenancy, policy, service and repo','Your practice merge request (one extra test in backend/src/modules/clients/rules.test.ts) is merged after your review partner approves it']::text[],array['pnpm install, copy backend/.env.example to backend/.env with local values only','pnpm dev:up (Postgres, Mailpit, MinIO), then pnpm db:reset (migrations and invented seed data)','Read backend/src/core/* and the clients reference module end to end: routes.ts, service.ts, repo.ts, rules.ts, tests']::text[],array['pnpm dev and open http://localhost:5173','Register, finish onboarding as Immersion lead, create a client, switch customer view and stage view, open the card','Read frontend/src/lib/api.ts and frontend/src/features/clients/* to see how a screen calls a contract']::text[],array['Routes only through defineRoute with a contract and a permission','Database access only in repo.ts, every query scoped by workspaceId','Other modules are used only through their index.ts','No secrets, tokens, passwords or emails in logs']::text[],array['Which file would you change to add one more field to a client card, and in which order?','Why does a hidden client card answer 404 and not 403?','What in GUARDRAILS.md surprised you, or would you push back on?']::text[],1010),
('G-1','Stage audit: Qualify','Start','Walk every Qualify screen in both prototype pages, every rule and gate for Qualify in the rules files, and every Qualify scenario in the acceptance files. Write down what is missing, unclear or contradictory before the contracts are frozen, so the gaps are found in week 1 and not in week 8.','As the Qualify owner I know every screen, rule and scenario of my stage, so that my contracts cover all of it and the team hears about gaps early.','Start','dev1',1,false,array['S-1']::text[],array[]::text[],array['docs/stages/QUALIFY.md','docs/blueprint/PHASE1_PLAN.md §15.4, §15.5','docs/blueprint/rules/intake.v1.yaml','docs/blueprint/prototype/index.html (Qualify tab, intake confirm)','docs/blueprint/prototype/app-flow-map.html (Qualify)']::text[],array['docs/stages/QUALIFY.md (Audit section)']::text[],array[]::text[],array['docs/stages/QUALIFY.md has an "Audit" section: each screen, rule and scenario is mapped to a contract or marked as a gap','Open questions are raised with the product owner before 27 November','The other three developers have read it before the contract review']::text[],array['List every endpoint Qualify needs and match it to docs/ARCHITECTURE.md §4','List every table and event, and who writes it']::text[],array['List every Qualify screen and state (empty, loading, error, locked) from the prototype','Note which role sees which tab (PHASE1_PLAN §15.4 tab table)']::text[],array['Plain words, verb and object on buttons, role titles only, no em dashes','Customer free text only in the pii schema; no personal names in events, logs or drafts']::text[],array['Which Qualify rule is the easiest to get wrong, and how will a test catch it?','Where does Qualify hand over to the next stage, and what exactly is passed?','Which prototype screen does not match the plan text, and which one wins?']::text[],1011),
('K-1','Freeze the Qualify contracts','Start','Turn the draft endpoints in contracts/src/clients.ts and contracts/src/intake.ts into real Zod schemas: params, query, body, response and permission for every Qualify endpoint, plus fixtures. The other three build against these from 27 November, so after the freeze a change is its own merge request reviewed by everyone.','As Developer 1 I publish exact request and response shapes for Qualify, so that the frontend, the backend and the other stages can build in parallel without guessing.','Contracts','dev1',2,true,array['G-1']::text[],array[]::text[],array['docs/ARCHITECTURE.md §4, §5','docs/stages/QUALIFY.md','docs/blueprint/PHASE1_PLAN.md §15.4, §15.5']::text[],array['contracts/src/clients.ts and contracts/src/intake.ts','contracts/src/fixtures/*']::text[],array[]::text[],array['pnpm verify passes with no draft contract left in your file','The contract coverage test shows every endpoint registered (stub or real)','Reviewed and approved by the other three developers before 27 November']::text[],array['Replace every z.unknown() placeholder in your contract file with a real schema; mark nothing as draft','Each stub route keeps answering 501 but now with the frozen schema, so callers type-check','Add fixtures (invented data only) next to the contract for tests and frontend mocks']::text[],array['Check every screen from your stage audit maps to at least one contract','Build one screen against the frozen contract with fixture data to prove the shapes are usable']::text[],array['Every input goes through the contract schema; unknown fields are rejected with 400','Customer free text only in the pii schema; no personal names in events, logs or drafts','Routes only through defineRoute with a contract and a permission']::text[],array['Which fields are optional, and why? Every optional field is a branch someone must test','Which response fields could leak data a role should not see?','Which of your endpoints are public, and what stops them being abused?']::text[],2012),
